const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let saved=[];try{saved=JSON.parse(localStorage.getItem('aegis-assessments')||'[]');if(!Array.isArray(saved))saved=[];saved=saved.filter(x=>x&&Array.isArray(x.findings)&&typeof x.url==='string')}catch{}let current=saved[0]||null,filter='all';
function persist(){try{localStorage.setItem('aegis-assessments',JSON.stringify(saved))}catch{toast('Browser storage unavailable. Export your report to keep it.')}}
function toast(t){$('toast').textContent=t;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',3500)}
function show(view){document.querySelectorAll('.view').forEach(x=>x.classList.toggle('hidden',x.id!==view));document.querySelectorAll('nav button').forEach(x=>x.classList.toggle('active',x.dataset.view===view));$('crumb-current').textContent=({overview:'Overview',scan:'New assessment',plan:'Test planner',findings:'Findings',history:'Assessment history'})[view];if(view==='findings')renderFindings();if(view==='history')renderHistory();window.scrollTo(0,0)}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>show(b.dataset.view));document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>show(b.dataset.go));$('start').onclick=()=>show('scan');document.querySelector('.brand').onclick=e=>{e.preventDefault();show('overview')};
function stats(){const f=current?.findings||[];$('stat-scans').textContent=saved.length;$('stat-findings').textContent=f.filter(x=>x.status!=='Passed').length;$('stat-high').textContent=f.filter(x=>x.severity==='High').length;$('stat-pass').textContent=f.filter(x=>x.status==='Passed').length;$('nav-count').textContent=f.filter(x=>x.status!=='Passed').length}
const sample="HTTP/1.1 200 OK\nContent-Type: text/html; charset=utf-8\nX-Content-Type-Options: nosniff\nSet-Cookie: session=[redacted]; Path=/; SameSite=Lax\nAccess-Control-Allow-Origin: *\n\n<html><body>Weather forecast sample</body></html>";
function assessment(raw,url,demo){const a={id:Date.now().toString(36),url,date:new Date().toISOString(),demo,findings:SecurityEngine.analyze(raw,url)};saved.unshift(a);saved=saved.slice(0,25);current=a;filter='all';persist();stats();show('findings')}
$('demo').onclick=()=>assessment(sample,'https://weather-demo.example',true);$('fill-demo').onclick=()=>{$('target').value='https://weather-demo.example';$('raw').value=sample;toast('Sample filled. Analysis will be labeled as demo.')};
$('scan-form').onsubmit=e=>{e.preventDefault();$('form-error').textContent='';try{const u=new URL($('target').value);if(!['http:','https:'].includes(u.protocol))throw Error('Use an HTTP or HTTPS URL.');if(u.username||u.password)throw Error('Remove credentials from the URL.');if(!$('authorized').checked)throw Error('Confirm authorization before continuing.');assessment($('raw').value,u.href,u.hostname==='weather-demo.example')}catch(err){$('form-error').textContent=err.message}};
function renderFindings(){document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('selected',b.dataset.filter===filter));$('demo-banner').classList.toggle('hidden',!current?.demo);if(!current){$('result-subtitle').textContent='Run an assessment or explore the demo to get started.';$('finding-list').innerHTML='<div class="empty">No assessment yet.<br>Analyze a response to see evidence and suggested fixes.</div>';$('result-count').textContent='';return;}$('result-subtitle').textContent=current.url+' · '+new Date(current.date).toLocaleString()+' · Imported response only';const fs=current.findings.filter(f=>filter==='all'||filter==='review'&&f.status!=='Passed'||filter==='passed'&&f.status==='Passed'||filter==='high'&&f.severity==='High');$('result-count').textContent=fs.length+' checks';$('finding-list').innerHTML=fs.length?fs.map(f=>`<details class="finding"><summary><span class="badge ${esc(f.severity)}">${esc(f.severity)}</span><span class="finding-title">${esc(f.title)}</span><span class="finding-status">${esc(f.status)}</span></summary><div class="detail"><h4>OBSERVED EVIDENCE</h4><div class="evidence">${esc(f.evidence)}</div><div class="remediation"><h4>SUGGESTED NEXT STEP</h4><p>${esc(f.fix)}</p></div><h4>CONTEXT</h4><p>${esc(f.why)}</p><span class="tag">CURATED GUIDANCE · NOT AI GENERATED</span></div></details>`).join(''):'<div class="empty">No checks match this filter.</div>'}
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;renderFindings()});
$('export').onclick=()=>{if(!current)return toast('Run an assessment first.');const report={tool:'Aegis v0.1',coverage:'Imported HTTP response only. No active scanning. Explanations are curated, not AI-generated.',...current};const blob=new Blob([JSON.stringify(report,null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='aegis-assessment-'+current.id+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('Report exported')};
function renderHistory(){$('history-list').innerHTML=saved.length?saved.map(a=>`<article class="history-card"><div><h3>${esc(a.url)}</h3><p>${esc(new Date(a.date).toLocaleString())} · ${a.demo?'Demo':'Imported evidence'} · ${a.findings.filter(f=>f.status!=='Passed').length} checks need review</p><p id="compare-${esc(a.id)}"></p></div><div class="history-actions"><button class="secondary" data-open="${esc(a.id)}">Open ↗</button><button class="secondary" data-compare="${esc(a.id)}">Compare previous</button></div></article>`).join(''):'<div class="empty">Your assessments will appear here.</div>';document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{current=saved.find(a=>a.id===b.dataset.open);filter='all';stats();show('findings')});document.querySelectorAll('[data-compare]').forEach(b=>b.onclick=()=>{const i=saved.findIndex(a=>a.id===b.dataset.compare),a=saved[i],prior=saved.slice(i+1).find(x=>x.url===a.url&&x.demo===a.demo);const out=$('compare-'+a.id);if(!prior){out.textContent='No earlier assessment for this target. Import a new response to compare.';return;}const old=new Map(prior.findings.map(f=>[f.id,f]));const changed=a.findings.filter(f=>!old.has(f.id)||old.get(f.id).status!==f.status||old.get(f.id).evidence!==f.evidence);const absent=prior.findings.filter(f=>!a.findings.some(n=>n.id===f.id));out.textContent=changed.length+' changed or new checks; '+absent.length+' previously observed checks absent. Differences reflect imported evidence, not verified fixes.'})}
const plans={weather:[['Protect provider API keys','Check frontend assets for secret keys. Public keys may be intentional; verify provider restrictions.'],['Check location input handling','In a test environment, verify unexpected city names and coordinates are rejected or displayed safely.'],['Review upstream quota controls','Confirm that caching and request limits prevent uncontrolled paid API usage.']],shop:[['Check order ownership','Using two test accounts, verify each account can view only its own orders.'],['Verify prices on the server','Confirm checkout uses trusted prices rather than client-submitted totals.'],['Check coupon business rules','Verify expiry, redemption limits, and intended eligibility in a test environment.']],college:[['Protect student records','Confirm that students cannot view another student’s marks.'],['Restrict grade updates','Verify teachers can update only their assigned classes.'],['Review administrative actions','Ensure only designated administrators can manage roles.']],saas:[['Check tenant isolation','Verify records stay within the correct organization.'],['Review role boundaries','Check that members cannot perform owner-only actions.'],['Protect exports','Confirm report downloads enforce the same access checks as the UI.']]};
function plan(){const items=[...plans[$('app-type').value]];if($('accounts').checked)items.push(['Review session security','Check cookie protections, logout, and access restrictions with test accounts.']);if($('paid').checked)items.push(['Enforce paid access on the server','Verify free accounts cannot access paid endpoints by bypassing the interface.']);items.push(['Inspect response configuration','Import a response into Aegis to check headers, cookies, and supported secret patterns.']);$('plan-results').innerHTML=items.map(([t,d],i)=>`<div class="checklist"><input type="checkbox" id="task-${i}" aria-label="Mark ${esc(t)} complete"><label for="task-${i}">${esc(t)}<p>${esc(d)}</p></label></div>`).join('')}
$('generate-plan').onclick=plan;$('clear').onclick=()=>{if(!confirm('Clear all assessments saved in this browser?'))return;saved=[];current=null;persist();stats();renderHistory();renderFindings();toast('Saved assessments cleared')};stats();plan();
